# Snippet 1: Iterating over Lists with Enumerate
heroes = ['Arthur', 'Merlin', 'Lancelot']
for idx, hero in enumerate(heroes):
    print(f'Slot {idx}: {hero}')

# Snippet 2: Iterating over Dictionary Keys and Values
stats = {'STR': 15, 'DEX': 12, 'INT': 8}
print('--- Stats ---')
for key, val in stats.items():
    print(f'{key} is at level {val}')

# Snippet 3: List of Dictionaries
party = [
    {'name': 'Arthur', 'hp': 100},
    {'name': 'Merlin', 'hp': 60}
]
for member in party:
    print(member['name'], 'has', member['hp'], 'health.')
